using System;using System.Data.SqlClient;using System.IO;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class BackupRestorePage:UserControl{Label status;public BackupRestorePage(){Dock=DockStyle.Fill;BackColor=Theme.Background;var p=Ui.Card();p.Dock=DockStyle.Top;p.Height=180;var b=Ui.Button(L.Fa?"ایجاد نسخه پشتیبان":"Create backup");b.Click+=(s,e)=>Backup();status=Ui.Label(L.Fa?"نسخه پشتیبان SQL Server در مسیر انتخابی ذخیره می‌شود.":"SQL Server backup will be saved to the selected path.");status.Top=65;status.Left=10;p.Controls.Add(b);p.Controls.Add(status);Controls.Add(p);}void Backup(){using(var d=new SaveFileDialog{Filter="SQL backup (*.bak)|*.bak",FileName="AshkanJobCenter-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".bak"})if(d.ShowDialog()==DialogResult.OK){try{var safe=d.FileName.Replace("'","''");Database.Exec("BACKUP DATABASE [AshkanJobCenterDB] TO DISK=N'"+safe+"' WITH INIT, CHECKSUM");status.Text=L.Fa?"پشتیبان با موفقیت ایجاد شد.":"Backup created successfully.";Database.Audit("Backup","System",d.FileName);}catch(Exception ex){MessageBox.Show(ex.Message);}}}}
}